package com.campusevents.ui;
import com.campusevents.service.AuthService;import javax.swing.*;import java.awt.*;
public class RegisterDialog extends JDialog {private final JTextField[] f=new JTextField[6];private final JPasswordField password=new JPasswordField(18);private final JComboBox<Integer> year=new JComboBox<>(new Integer[]{1,2,3,4,5,6});public RegisterDialog(JFrame owner){super(owner,"Student signup",true);setSize(420,420);setLocationRelativeTo(owner);String[] labels={"Full name","Email","College/student ID","Department","Phone"};JPanel p=new JPanel(new GridLayout(0,2,7,7));p.setBorder(BorderFactory.createEmptyBorder(18,18,18,18));for(int i=0;i<5;i++){f[i]=new JTextField(18);p.add(new JLabel(labels[i]));p.add(f[i]);}p.add(new JLabel("Password"));p.add(password);p.add(new JLabel("Academic year"));p.add(year);JButton b=new JButton("Create account");p.add(new JLabel());p.add(b);setContentPane(p);b.addActionListener(e->save());}private void save(){try{new AuthService().register(f[0].getText(),f[1].getText(),new String(password.getPassword()),f[2].getText(),f[3].getText(),(Integer)year.getSelectedItem(),f[4].getText());JOptionPane.showMessageDialog(this,"Account created. Sign in to continue.");dispose();}catch(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Signup error",JOptionPane.ERROR_MESSAGE);}}}
